resource "aws_iam_policy" "s3_read_only" {
  name        = "s3-read-only-policy"
  description = "Read-only access ke S3 bucket tertentu"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          "arn:aws:s3:::my-company-data-bucket-secure",
          "arn:aws:s3:::my-company-data-bucket-secure/*"
        ]
      }
    ]
  })
}

